    if (!p) return { name: n, meta: v115TradMeta(n) };
    var lon = p.lon,
      lat = p.lat || 0;
    if (n === "月亮") {
      try {
        var mm = smMoon(jd);
        lon = mm.lon;
        lat = mm.lat || 0;
      } catch (_) {}
    }
    var xi = null,
      full = "—",
      si = "—",
      duzhu = "—";
